const p=$json.body??$json;
const clean=(v)=>(v??'').toString().trim().replace(/\s+/g,' ');
const message=clean(p.message||p.enquiry||p.description);
const rawService=clean(p.service).toLowerCase();
const text=`${rawService} ${message}`.toLowerCase();
const aliases=[['water damage','restoration_review'],['restoration','restoration_review'],['hot water extraction','carpet_cleaning'],['hwe','carpet_cleaning'],['encapsulation','carpet_cleaning'],['encap','carpet_cleaning'],['wool carpet','carpet_cleaning'],['stain removal','carpet_cleaning'],['spot removal','carpet_cleaning'],['urine extraction','carpet_cleaning'],['urine treatment','carpet_cleaning'],['carpet repair','carpet_cleaning'],['carpet cleaning','carpet_cleaning'],['leather','upholstery_cleaning'],['upholstery','upholstery_cleaning'],['couch','upholstery_cleaning'],['sofa','upholstery_cleaning'],['high pressure tile','tile_grout'],['tile & grout','tile_grout'],['tile and grout','tile_grout'],['tile','tile_grout'],['grout','tile_grout'],['natural stone','hard_floor'],['epoxy','hard_floor'],['rubber tile','hard_floor'],['rubber flooring','hard_floor'],['gym flooring','hard_floor'],['gym floor','hard_floor'],['vinyl','hard_floor'],['stone','hard_floor'],['concrete','hard_floor'],['strip and seal','hard_floor_restoration'],['strip & seal','hard_floor_restoration'],['recoat','hard_floor_restoration'],['burnishing','hard_floor_restoration'],['buffing','hard_floor_restoration'],['micron sealing','hard_floor_restoration'],['penetrating sealer','hard_floor_restoration'],['sealing','hard_floor_restoration'],['stripping','hard_floor_restoration'],['carpet','carpet_cleaning']];
let service='unknown';
for(const [a,c] of aliases){if(text.includes(a)){service=c;break;}}
const lead={source:clean(p.source||'unknown').toLowerCase(),customer_name:clean(p.customer_name||p.name),email:clean(p.email),phone:clean(p.phone||p.mobile),job_address:clean(p.job_address||p.address||p.site_address),suburb:clean(p.suburb||p.city),postcode:clean(p.postcode),service,message,measurements:clean(p.measurements||p.area),preferred_timing:clean(p.preferred_timing||p.date_requested),attachments_present:Boolean(p.attachments_present||p.attachments)};
const correlation_id=clean(p.correlation_id);
const idempotency_key=clean(p.idempotency_key);
const missing=[];
if(!lead.customer_name)missing.push('customer_name');
if(!(lead.email||lead.phone))missing.push('contact_method');
if(!(lead.job_address||(lead.suburb&&lead.postcode)))missing.push('job_location');
if(lead.service==='unknown')missing.push('service');
if(!correlation_id)missing.push('correlation_id');
if(!idempotency_key)missing.push('idempotency_key');
const risks=[];
const patterns={water_or_flood:/\b(flood|flooded|water damage|sewage|black water|burst pipe)\b/i,mould_or_contamination:/\b(mould|mold|biohazard|blood|faec|feces|needle|contamination)\b/i,guarantee_request:/\b(guarantee|100%|definitely remove|promise.*remove)\b/i,insurance_or_liability:/\b(insurance claim|liability|compensation|damages claim)\b/i,urgent_health_safety:/\b(asbestos|chemical spill|hazardous|toxic)\b/i};
for(const [k,r] of Object.entries(patterns)){if(r.test(text))risks.push(k);}
if(service==='restoration_review'||risks.some(x=>['water_or_flood','mould_or_contamination','urgent_health_safety'].includes(x)))risks.push('restoration_requires_review');
const uniqueRisks=[...new Set(risks)].sort();
const review=missing.length>0||uniqueRisks.length>0;
return [{json:{
  correlation_id,
  idempotency_key,
  lead,
  missing_fields:missing,
  risk_flags:uniqueRisks,
  human_review_required:review,
  safe_acknowledgement_allowed:uniqueRisks.length===0,
  servicem8_job_draft:{
    status:'Quote',
    job_address:lead.job_address||[lead.suburb,lead.postcode].filter(Boolean).join(', '),
    job_description:`BVP correlation ID: ${correlation_id}\nBVP idempotency key: ${idempotency_key}\nVoila Floor lead source: ${lead.source}\nService: ${lead.service}\nCustomer enquiry: ${lead.message}\nAI/automation status: DRAFT ONLY — scope and price require human review.`
  },
  stage:'DRY_RUN_NO_WRITES'
}}];
